//! Experimental TypeScript 7.1 checker backend (`--experimental-semantic-types`).
//!
//! Spawns `tsc --api` (through `caliper-docgen-tsc-client`), asks it for the props of each component the structural
//! pass found, and hands `caliper-docgen-core` a [`SemanticOutcome`] to merge (ADR 0006, ADR 0007). It is always
//! compiled in and enabled at run time. Any failure to start or finish (no `tsc`, an unpinned version, a crash, a
//! timeout) yields an outcome with no components and one diagnostic, never an error: the structural result is
//! complete on its own.
//!
//! This slice answers function components exported by name or as `default`. Class components, overloaded or
//! generic components and union props types keep their structural result and say why.

#![deny(missing_docs)]

mod component;
mod convert;
mod locate;
mod on_demand;
mod rpc;

pub use on_demand::{OnDemand, OnDemandConfig};

use std::sync::Arc;
use std::time::Duration;

use caliper_docgen_core::types::ExtractionOutput;
use caliper_docgen_core::types::semantic::{PropInterner, SemanticComponent, SemanticFallback, SemanticOutcome};
use caliper_docgen_tsc_client::{Supervisor, SupervisorConfig};
use camino::{Utf8Path, Utf8PathBuf};
use rustc_hash::FxHashMap;
use tokio::sync::Semaphore;
use tokio::task::JoinSet;

use crate::component::Answer;
use crate::convert::Converter;
use crate::rpc::{CallError, Rpc};

/// The `typescript` releases whose protocol this backend was traced against: the 7.1 series, from `7.1.0-beta` on. The
/// protocol has no version handshake, so the package's `package.json` version and the initialize call that follows
/// the spawn are the whole check; a build that fails either takes the structural result with one warning.
pub const SUPPORTED_VERSIONS: &[&str] = &["7.1"];

/// How many files are asked about at once. `tsc` answers requests one at a time; this keeps it from idling on round
/// trips.
const FILES_IN_FLIGHT: usize = 16;

/// A component the structural pass found.
pub use caliper_docgen_core::types::semantic::SemanticTarget as Target;

/// The components of `output`, in output order.
pub fn targets_of(output: &ExtractionOutput) -> Vec<Target> {
    output
        .components
        .values()
        .map(|entry| Target {
            file_path: entry.file_path.clone(),
            display_name: entry.display_name.clone(),
            exported: entry.exported,
            described: entry
                .props
                .values()
                .filter(|prop| !prop.description.is_empty())
                .map(|prop| prop.name.clone())
                .collect(),
            // The whole-project merge leaves `@types/react`'s props to the inheritance layers.
            react_wanted: Some(Default::default()),
        })
        .collect()
}

/// One whole-project request to the checker: the components to answer for, and how to reach `tsc`. Built with
/// [`SemanticRequest::new`] and answered by [`resolve`].
#[derive(Debug, Clone)]
pub struct SemanticRequest {
    /// Where `tsc` finds `node_modules`; its `--cwd`, and where the search for `typescript` starts.
    pub project_root: Utf8PathBuf,
    /// A tsconfig whose compiler options the checker uses (read with `parseConfigFile`); with none, a default set.
    pub tsconfig: Option<Utf8PathBuf>,
    /// An explicit `tsc` binary, instead of `node_modules/typescript/bin/tsc` above `project_root`.
    pub tsc_path: Option<Utf8PathBuf>,
    /// The components to ask about.
    pub targets: Vec<Target>,
    /// Bound on each request, and on the `tsc` start-up handshake.
    pub request_timeout: Duration,
    /// The `typescript` versions the checker may report; one that is not among them is a start-up failure.
    pub expected_versions: &'static [&'static str],
    /// Write every request and its answer here as JSON, to refresh the replay fixture the tests use.
    pub record_to: Option<Utf8PathBuf>,
    /// Environment for the `tsc` process; the tests use it to pick a replay scenario.
    pub extra_env: Vec<(String, String)>,
    /// Compiler options of a `tsc` session that is already initialized. A warm checker sets this once so a request
    /// only builds its program.
    pub(crate) prepared_options: Option<serde_json::Value>,
}

impl SemanticRequest {
    /// A request for `targets` under `project_root`, with a 60 second timeout, the supported versions, and no
    /// tsconfig or explicit `tsc` path.
    pub fn new(project_root: Utf8PathBuf, targets: Vec<Target>) -> Self {
        Self {
            project_root,
            tsconfig: None,
            tsc_path: None,
            targets,
            request_timeout: Duration::from_secs(60),
            expected_versions: SUPPORTED_VERSIONS,
            record_to: None,
            extra_env: Vec::new(),
            prepared_options: None,
        }
    }
}

/// Resolves the request's components with the checker. Blocks; builds its own single-threaded runtime, so it must
/// not be called from inside one.
pub fn resolve(request: SemanticRequest) -> SemanticOutcome {
    let runtime = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
        Ok(runtime) => runtime,
        Err(error) => return SemanticOutcome::unavailable(format!("could not start an async runtime: {error}")),
    };
    runtime.block_on(run(request))
}

/// The exported targets by file, in first-seen order, and an outcome that already holds a fallback for each target
/// the checker cannot be asked about.
fn group_by_file(request: &SemanticRequest) -> (SemanticOutcome, FxHashMap<&Utf8Path, Vec<&Target>>, Vec<&Utf8Path>) {
    let mut outcome = SemanticOutcome::default();
    let mut by_file: FxHashMap<&Utf8Path, Vec<&Target>> = FxHashMap::default();
    let mut order: Vec<&Utf8Path> = Vec::new();
    for target in &request.targets {
        if !target.exported {
            outcome.fallbacks.push(fallback_of(target, "not exported by its module"));
            continue;
        }
        let group = by_file.entry(target.file_path.as_path()).or_default();
        if group.is_empty() {
            order.push(target.file_path.as_path());
        }
        group.push(target);
    }
    (outcome, by_file, order)
}

fn supervisor_config(request: &SemanticRequest) -> Result<SupervisorConfig, String> {
    let tsc_path = locate::find_tsc(&request.project_root, request.tsc_path.as_deref())?;
    let mut config = SupervisorConfig::new(tsc_path, request.project_root.clone(), request.expected_versions);
    config.handshake_timeout = request.request_timeout;
    config.extra_env.clone_from(&request.extra_env);
    Ok(config)
}

async fn run(request: SemanticRequest) -> SemanticOutcome {
    if !request.targets.iter().any(|target| target.exported) {
        return group_by_file(&request).0;
    }
    let config = match supervisor_config(&request) {
        Ok(config) => config,
        Err(reason) => return SemanticOutcome::unavailable(reason),
    };
    let supervisor = match Supervisor::spawn(config).await {
        Ok(supervisor) => supervisor,
        Err(error) => return SemanticOutcome::unavailable(error.to_string()),
    };
    let outcome = answer_with(&supervisor, &request).await;
    supervisor.shutdown().await.ok();
    outcome
}

/// Answers the request's targets with a checker that is already running: one program rooted at their files.
async fn answer_with(supervisor: &Supervisor, request: &SemanticRequest) -> SemanticOutcome {
    let (mut outcome, by_file, order) = group_by_file(request);
    if order.is_empty() {
        return outcome;
    }
    let files: Vec<String> = order.iter().map(|file| file.to_string()).collect();
    match session(supervisor, request, &files, &by_file, &order).await {
        Ok(mut answered) => {
            outcome.components.append(&mut answered.components);
            outcome.fallbacks.append(&mut answered.fallbacks);
            outcome
        }
        Err(error) => SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")),
    }
}

async fn session(
    supervisor: &Supervisor,
    request: &SemanticRequest,
    files: &[String],
    by_file: &FxHashMap<&Utf8Path, Vec<&Target>>,
    order: &[&Utf8Path],
) -> Result<SemanticOutcome, CallError> {
    let started = std::time::Instant::now();
    let opened = match &request.prepared_options {
        Some(options) => {
            Rpc::open_with(supervisor.client(), request.request_timeout, options, files, request.record_to.is_some())
                .await
        }
        None => {
            Rpc::open(
                supervisor.client(),
                request.request_timeout,
                request.tsconfig.as_ref().map(|path| path.as_str()),
                files,
                request.record_to.is_some(),
            )
            .await
        }
    };
    let rpc = Arc::new(opened?);
    let opened = started.elapsed();
    let converter = Converter::new(rpc.clone());
    let limit = Arc::new(Semaphore::new(FILES_IN_FLIGHT));
    let interner = Arc::new(PropInterner::default());

    let mut tasks = JoinSet::new();
    for file in order {
        let targets: Vec<Target> = by_file.get(file).into_iter().flatten().map(|target| (*target).clone()).collect();
        let (rpc, converter, limit, interner) = (rpc.clone(), converter.clone(), limit.clone(), interner.clone());
        tasks.spawn(async move {
            let _permit = limit.acquire().await;
            answer_file(&rpc, &converter, &interner, targets).await
        });
    }

    let mut outcome = SemanticOutcome::default();
    let mut failure = None;
    while let Some(joined) = tasks.join_next().await {
        match joined {
            Ok(Ok(mut answered)) => {
                outcome.components.append(&mut answered.components);
                outcome.fallbacks.append(&mut answered.fallbacks);
            }
            Ok(Err(error)) => {
                failure = Some(error);
                tasks.abort_all();
            }
            // A panic inside a worker must not silently leave its components structural.
            Err(joined) if joined.is_panic() => {
                failure = Some(CallError::Fatal("a worker panicked".to_string()));
                tasks.abort_all();
            }
            // A cancelled task is one this loop aborted after a failure.
            Err(_cancelled) => {}
        }
    }
    if let Some(error) = failure {
        return Err(error);
    }

    if let (Some(path), Some(recording)) = (&request.record_to, rpc.recording())
        && let Ok(json) = serde_json::to_string_pretty(&recording)
        && let Err(error) = std::fs::write(path, json)
    {
        tracing::warn!("could not write the recording to {path}: {error}");
    }
    tracing::debug!(
        requests = ?rpc.calls(),
        files = files.len(),
        program_ms = opened.as_millis() as u64,
        total_ms = started.elapsed().as_millis() as u64,
        "semantic backend finished"
    );
    rpc.release().await;
    outcome.components.sort_by(|a, b| (&a.file_path, &a.display_name).cmp(&(&b.file_path, &b.display_name)));
    outcome.fallbacks.sort_by(|a, b| (&a.file_path, &a.display_name).cmp(&(&b.file_path, &b.display_name)));
    Ok(outcome)
}

fn fallback_of(target: &Target, reason: &str) -> SemanticFallback {
    SemanticFallback {
        file_path: target.file_path.clone(),
        display_name: target.display_name.clone(),
        reason: reason.to_string(),
    }
}

/// A fatal error aborts the run; a call the checker rejected only sends that component to its structural result.
async fn answer_file(
    rpc: &Rpc,
    converter: &Converter,
    interner: &PropInterner,
    targets: Vec<Target>,
) -> Result<SemanticOutcome, CallError> {
    let mut outcome = SemanticOutcome::default();
    let Some(first) = targets.first() else { return Ok(outcome) };
    let exports = match module_exports(rpc, first.file_path.as_str()).await {
        Ok(Some(exports)) => exports,
        Ok(None) | Err(CallError::Rejected(_)) => {
            outcome
                .fallbacks
                .extend(targets.iter().map(|target| fallback_of(target, "not part of the checker's program")));
            return Ok(outcome);
        }
        Err(fatal) => return Err(fatal),
    };

    for target in &targets {
        match component::props_of(rpc, converter, interner, &exports, target).await {
            Ok(Answer::Props(props)) => outcome.components.push(SemanticComponent {
                file_path: target.file_path.clone(),
                display_name: target.display_name.clone(),
                props,
            }),
            Ok(Answer::Fallback(reason)) => outcome.fallbacks.push(fallback_of(target, &reason)),
            Err(CallError::Rejected(message)) => {
                outcome.fallbacks.push(fallback_of(target, &format!("the checker rejected a request: {message}")));
            }
            Err(fatal) => return Err(fatal),
        }
    }
    Ok(outcome)
}

async fn module_exports(rpc: &Rpc, file: &str) -> Result<Option<Vec<rpc::SymbolInfo>>, CallError> {
    let Some(module) = rpc.source_file_symbol(file).await? else { return Ok(None) };
    Ok(Some(rpc.exports_of_module(&module.reference).await?))
}
//! Finding the `tsc` binary the project installed.

use camino::{Utf8Path, Utf8PathBuf};

/// `explicit` if given (it must exist), else the nearest `node_modules/typescript/bin/tsc` at or above `project_root`.
/// The version is checked later, when the process is spawned.
pub(crate) fn find_tsc(project_root: &Utf8Path, explicit: Option<&Utf8Path>) -> Result<Utf8PathBuf, String> {
    if let Some(path) = explicit {
        return if path.is_file() { Ok(path.to_owned()) } else { Err(format!("no tsc binary at {path}")) };
    }
    project_root
        .ancestors()
        .map(|dir| dir.join("node_modules").join("typescript").join("bin").join("tsc"))
        .find(|candidate| candidate.is_file())
        .ok_or_else(|| {
            format!(
                "no node_modules/typescript/bin/tsc at or above {project_root}; install `typescript@beta` (7.1) or pass \
                 --tsc-path"
            )
        })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_nearest_installed_typescript_above_the_project_wins() {
        let dir = tempfile::tempdir().unwrap();
        let root = Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).unwrap();
        let bin = root.join("node_modules/typescript/bin");
        std::fs::create_dir_all(&bin).unwrap();
        std::fs::write(bin.join("tsc"), "").unwrap();
        let project = root.join("packages/ui");
        std::fs::create_dir_all(&project).unwrap();

        assert_eq!(find_tsc(&project, None), Ok(bin.join("tsc")));
    }

    #[test]
    fn a_project_without_typescript_says_where_it_looked() {
        let dir = tempfile::tempdir().unwrap();
        let root = Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).unwrap();

        let error = find_tsc(&root, None).unwrap_err();

        assert!(error.contains("no node_modules/typescript/bin/tsc"), "{error}");
    }

    #[test]
    fn an_explicit_path_that_does_not_exist_is_an_error_not_a_search() {
        let dir = tempfile::tempdir().unwrap();
        let root = Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).unwrap();

        assert_eq!(find_tsc(&root, Some(&root.join("nope"))), Err(format!("no tsc binary at {}", root.join("nope"))));
    }
}
use std::process::{ExitStatus, Stdio};
use std::sync::Arc;
use std::time::{Duration, Instant};

use camino::{Utf8Path, Utf8PathBuf};
use tokio::io::AsyncBufReadExt;
use tokio::process::{Child, Command};

use crate::client::{Client, TaggedResponse};
use crate::error::TscClientError;

const DEFAULT_HANDSHAKE_TIMEOUT: Duration = Duration::from_secs(10); // measured 33-72ms; generous headroom
const SHUTDOWN_GRACE: Duration = Duration::from_secs(2);
const MAX_RESTARTS: u32 = 3;
const RESTART_WINDOW: Duration = Duration::from_secs(60);
const BACKOFF_STEPS: [Duration; 3] =
    [Duration::from_millis(200), Duration::from_millis(400), Duration::from_millis(800)];
const BACKOFF_MAX: Duration = Duration::from_secs(5);

/// How a [`Supervisor`] starts `tsc`, how long it waits, and how large a frame it accepts. Build one with
/// [`SupervisorConfig::new`] and adjust the public fields.
#[derive(Debug, Clone)]
pub struct SupervisorConfig {
    /// Path to the `tsc` binary, e.g. `node_modules/typescript/bin/tsc` — resolving
    /// that path is the caller's job, not this crate's.
    pub tsc_path: Utf8PathBuf,
    /// Passed as `tsc --api --async --cwd <cwd>`.
    pub cwd: Utf8PathBuf,
    /// `tsc_path`'s adjacent `package.json` "version" must match one of these, checked before every spawn. An entry
    /// is an exact version (`7.1.0-beta`) or a `major.minor` series (`7.1`, which takes `7.1.0`, `7.1.0-rc.1` and
    /// `7.1.4`, not `7.10.0`). The protocol has no version handshake (ADR 0006), so this and the initialize call
    /// that follows the spawn are the whole check — the caller decides which builds it has traced the protocol on.
    pub expected_versions: &'static [&'static str],
    /// How long a start-up handshake may take before it fails; 10 seconds by default.
    pub handshake_timeout: Duration,
    /// The largest frame body the reader accepts; a larger declared length ends the session with `OversizedFrame`.
    pub max_frame_bytes: usize,
    /// Extra environment variables for the spawned process. Empty for real use; tests
    /// use this to pick a `fake-tsc` scenario via `FAKE_TSC_SCENARIO`.
    pub extra_env: Vec<(String, String)>,
}

impl SupervisorConfig {
    /// A configuration for the `tsc` at `tsc_path`, run in `cwd`, that accepts the `expected_versions`, with a 10 second
    /// handshake timeout, the default frame cap and no extra environment.
    pub fn new(tsc_path: Utf8PathBuf, cwd: Utf8PathBuf, expected_versions: &'static [&'static str]) -> Self {
        Self {
            tsc_path,
            cwd,
            expected_versions,
            handshake_timeout: DEFAULT_HANDSHAKE_TIMEOUT,
            max_frame_bytes: crate::transport::DEFAULT_MAX_FRAME_BYTES,
            extra_env: Vec::new(),
        }
    }
}

fn check_version(tsc_path: &Utf8Path, expected: &'static [&'static str]) -> Result<(), TscClientError> {
    let reason_at = |reason: String| TscClientError::VersionCheckFailed { path: tsc_path.to_owned(), reason };

    let Some(package_json) =
        tsc_path.parent().and_then(|bin_dir| bin_dir.parent()).map(|pkg_dir| pkg_dir.join("package.json"))
    else {
        return Err(reason_at("tsc_path has no grandparent directory to find package.json in".to_string()));
    };

    let contents = std::fs::read_to_string(&package_json)
        .map_err(|source| reason_at(format!("reading {package_json}: {source}")))?;
    let value: serde_json::Value =
        serde_json::from_str(&contents).map_err(|source| reason_at(format!("parsing {package_json}: {source}")))?;
    let Some(found) = value.get("version").and_then(|v| v.as_str()) else {
        return Err(reason_at(format!("{package_json} has no \"version\" string")));
    };

    if expected.iter().any(|entry| version_matches(found, entry)) {
        Ok(())
    } else {
        Err(TscClientError::UnsupportedVersion { path: tsc_path.to_owned(), found: found.to_string(), expected })
    }
}

/// Whether `found` is `entry` or a release of the `entry` series: `7.1` takes `7.1.0-beta` and `7.1.3`, not `7.10.0`.
fn version_matches(found: &str, entry: &str) -> bool {
    found == entry || found.strip_prefix(entry).is_some_and(|rest| rest.starts_with(['.', '-']))
}

fn spawn_stderr_drain(stderr: tokio::process::ChildStderr) {
    // Must be continuously drained: an unread stderr pipe fills its OS buffer and can
    // deadlock the child. Logged at debug, not warn — tsc's own diagnostic chatter
    // isn't inherently an error, but it's valuable when a crash needs explaining.
    tokio::spawn(async move {
        let mut lines = tokio::io::BufReader::new(stderr).lines();
        while let Ok(Some(line)) = lines.next_line().await {
            tracing::debug!(target: "tsc_client::stderr", "{line}");
        }
    });
}

/// Spawns one `tsc --api` process and wires up its transport. Split out from
/// `Supervisor::spawn`/`restart` so a restart can replace the process/client pair
/// without losing the restart-attempt bookkeeping a fresh `Supervisor` would
/// otherwise reset.
async fn spawn_process(config: &SupervisorConfig) -> Result<(Child, Client), TscClientError> {
    check_version(&config.tsc_path, config.expected_versions)?;

    let mut command = Command::new(config.tsc_path.as_std_path());
    command.arg("--api").arg("--async").arg("--cwd").arg(config.cwd.as_std_path());
    command.stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped());
    command.envs(config.extra_env.iter().map(|(k, v)| (k.as_str(), v.as_str())));
    // Best-effort fallback if `Supervisor::shutdown` is never called — this alone
    // doesn't guarantee reaping (Drop can't await), only `.shutdown()` does.
    command.kill_on_drop(true);

    let mut child = command
        .spawn()
        .map_err(|source| TscClientError::SpawnFailed { path: config.tsc_path.clone(), source: Arc::new(source) })?;

    let Some(stdin) = child.stdin.take() else { unreachable!("stdin is None despite Stdio::piped()") };
    let Some(stdout) = child.stdout.take() else { unreachable!("stdout is None despite Stdio::piped()") };
    let Some(stderr) = child.stderr.take() else { unreachable!("stderr is None despite Stdio::piped()") };

    spawn_stderr_drain(stderr);
    let client = Client::connect(stdin, stdout, config.max_frame_bytes);

    Ok((child, client))
}

/// Owns one `tsc --api` child process across its lifetime: spawn, version check,
/// crash-triggered restart (bounded, to avoid a restart storm), and shutdown/reaping.
pub struct Supervisor {
    child: Child,
    client: Client,
    config: SupervisorConfig,
    restart_attempts: Vec<Instant>,
    /// Set once a restart-storm cap is hit. Terminal — every later call short-circuits
    /// without touching the process again.
    failed: bool,
}

impl Supervisor {
    /// Starts `tsc --api` and returns once its session is up.
    ///
    /// # Errors
    ///
    /// [`TscClientError::SpawnFailed`] when the binary cannot be started, and
    /// [`TscClientError::UnsupportedVersion`] or [`TscClientError::VersionCheckFailed`] when its `package.json` version
    /// is not one of the configured `expected_versions`.
    pub async fn spawn(config: SupervisorConfig) -> Result<Self, TscClientError> {
        let (child, client) = spawn_process(&config).await?;
        Ok(Self { child, client, config, restart_attempts: Vec::new(), failed: false })
    }

    /// The current session's low-level handle. Cheap to clone. A clone obtained before a
    /// supervisor-driven restart fails immediately with the reason its session closed with
    /// (`Crashed`, `Write`, `Read`, `MalformedFrame` or `OversizedFrame`) — call this again to get the live one. A
    /// clone held across [`Supervisor::shutdown`] fails with `SessionClosed`.
    pub fn client(&self) -> Client {
        self.client.clone()
    }

    /// The operating system's id of the running `tsc` process, `None` once it has exited.
    pub fn process_id(&self) -> Option<u32> {
        self.child.id()
    }

    /// True while the current session is open and the supervisor hasn't permanently failed. A crash between calls
    /// to this method and the next `request()` is still possible — this is a snapshot, not a guarantee.
    pub fn is_alive(&self) -> bool {
        self.client.closed().is_none() && !self.failed
    }

    /// Sends a request through the current session. A session that ended before the call is restarted first
    /// (budget permitting); one that ends during the call is restarted and the call retried once. At most one
    /// restart per call, so a request lost to a crash is never silently replayed more than once. A `Timeout` on a
    /// live session restarts nothing.
    ///
    /// Worst case is one restart plus one retry: `deadline` applies to each attempt separately, and a restart adds up
    /// to 800ms of backoff plus the spawn.
    pub async fn request(
        &mut self,
        method: &str,
        params: serde_json::Value,
        deadline: Duration,
    ) -> Result<TaggedResponse, TscClientError> {
        if self.failed {
            return Err(self.storm());
        }

        let restarted_first = self.client.closed().is_some();
        if restarted_first {
            self.restart().await?;
        }

        let result = self.client.request(method, params.clone(), deadline).await;
        if result.is_err() && !restarted_first && self.client.closed().is_some() {
            self.restart().await?;
            return self.client.request(method, params, deadline).await;
        }
        result
    }

    fn storm(&self) -> TscClientError {
        TscClientError::RestartStormDetected { attempts: self.restart_attempts.len() as u32, window: RESTART_WINDOW }
    }

    async fn restart(&mut self) -> Result<(), TscClientError> {
        let now = Instant::now();
        self.restart_attempts.retain(|attempt| now.duration_since(*attempt) < RESTART_WINDOW);

        if self.restart_attempts.len() as u32 >= MAX_RESTARTS {
            self.failed = true;
            return Err(self.storm());
        }

        let backoff = BACKOFF_STEPS.get(self.restart_attempts.len()).copied().unwrap_or(BACKOFF_MAX);
        // Counted before the spawn and the backoff: a spawn failure or a caller cancelling this call mid-restart still
        // burns one attempt, by design.
        self.restart_attempts.push(now);
        tokio::time::sleep(backoff).await;

        // Best-effort cleanup of the crashed process before respawning — it may
        // already be gone, so failures here are expected and ignored.
        self.child.start_kill().ok();
        self.child.wait().await.ok();

        let (child, client) = spawn_process(&self.config).await?;
        self.child = child;
        self.client = client;
        Ok(())
    }

    /// Ends the session and guarantees the child is reaped, never left as a zombie: close the session (fails
    /// in-flight requests with `SessionClosed` and makes the child see stdin EOF), race a grace period against a
    /// clean exit, force-kill past it, then unconditionally wait so the OS process table entry is always cleared.
    /// Returns the reaped exit status.
    pub async fn shutdown(mut self) -> Result<ExitStatus, TscClientError> {
        self.client.close();

        match tokio::time::timeout(SHUTDOWN_GRACE, self.child.wait()).await {
            Ok(waited) => waited.map_err(|source| TscClientError::Reap(Arc::new(source))),
            Err(_elapsed) => {
                self.child.start_kill().ok();
                // Unconditional — never left unreaped.
                self.child.wait().await.map_err(|source| TscClientError::Reap(Arc::new(source)))
            }
        }
    }
}

